select public.program_source_procedure_set('Irvine Valley College', $proc${"v": 1, "college": "Irvine Valley College", "reader": "kb/_program_requirements_pilot.py (robots.txt first, the census's delay and user agent); a capture follows links on the catalog's host only (lesson 24)", "hosts": [{"host": "irvine.curriqunet.com", "access": "open", "platform": "curriqunet", "note": "The 2026-27 catalog (Catalog/iq/48953). A program view opens by click and its text names few courses; each view links its own PDF export (Catalog/Export?id=4690&outlineId=<outline>), which names the listed courses. Art A.A. 10265's view is iq/48959/49229/51485/49348 and its export outlineId 51485 (capture run 37487454632)."}, {"host": "www.ivc.edu", "access": "open", "platform": "custom_html", "note": "All Program Maps (/node/3220): every map printed whole on one paginated page (seven pages, about 200 maps) as tab-separated tables under each term. Answered on 2026-10-04 (sequence probe run 37198225537) and read on 2026-10-05 (college page read run 37372136739)."}], "steps": [{"run": "37198225537", "date": "2026-10-04", "plan": "the registry-aware sequence probe", "found": "All Program Maps answers; filed as an open sequence source."}, {"run": "37372136739", "date": "2026-10-05", "plan": "kb/_program_map_parse.py", "found": "The Art A.A. map names 5 of its 23 listed courses (the required core) and leaves four slots from List A or B; ART 85 Life Drawing I, the college's one course carrying CPL in MAP (165 students), sits in Semester 3 (kb/program_requirements_pilot/sequences/ivc_10265.json)."}, {"run": "37487454632", "date": "2026-10-06", "plan": "capture, sample maps (curriQunet click-through, then the view's PDF export)", "found": "Art A.A. 10265: 21 of 23 listed codes (coverage 0.91); extraction passes at 27 units."}], "answers": [{"question": "Where the catalog prints Art A.A. 10265's requirements", "status": "answered", "answer": "The program view's PDF export on irvine.curriqunet.com (run 37487454632)."}, {"question": "Whether the college publishes term-by-term maps a reader can open", "status": "answered", "answer": "Yes: All Program Maps on www.ivc.edu, read in run 37372136739."}], "open": [{"question": "Art A.A. 10265's record against the catalog", "next": "A person reads the record (the Progress view's call on Sam)."}, {"question": "ARTH 25 and 26 in the catalog against ARTH C1100 and C1200 in the state file", "next": "A gap for the college, kept as a draft for the college; never a misread."}], "nuances": ["The catalog still prints ARTH 25 and 26 where the state file lists the common-numbered ARTH C1100 and C1200; the record keeps the catalog's codes.", "The catalog prints ART 195 and ART 91 as the same as DMA 195 and DMA 91; the record does not list the DMA codes as separate alternatives.", "A map that names the required core and leaves list slots is a correct map: coverage is reported and never gates.", "Art A.A. requires ART 85 and lists it again among its electives; a course counts once (S340)."], "requests": [], "workarounds": [{"for": "A curriQunet program view whose text names few courses", "tried": "The view's own Export Page as PDF (lesson 29)", "result": "worked (21 of 23 codes)"}], "request_ready": false}$proc$::jsonb, 'S344 SkyWaypoint, 2026-10-08 (scheduled run; handoff 344 priority 1)', 'none') as result;
select public.program_source_procedure_set('San Diego Miramar College', $proc${"v": 1, "college": "San Diego Miramar College", "reader": "kb/_program_requirements_pilot.py (robots.txt first, the census's delay and user agent); a capture follows links on the catalog's host only (lesson 24)", "hosts": [{"host": "sdccd.curriqunet.com", "access": "open", "platform": "curriqunet", "note": "The 2026-27 catalog under the alias miramar26-27 (catalog/alias/miramar26-27/iq/20891). San Diego mints one alias a year, and the district site lists every sibling's catalog: City College's city26-27 is not Miramar's (lesson 12). Program views open by click and print only the site's navigation; each links Export Page as PDF (Catalog/Export?id=71&outlineId=<outline>), which names every listed course (capture run 6, 37172202580)."}, {"host": "san-diego-miramar.programmapper.com", "access": "refused", "platform": "outside", "note": "The Program Pathways Mapper, linked from sdmiramar.edu/program-mapper. Answered all seven requests 403 on 2026-10-04 (run 37197332656); all 17 mapper hosts probed that day did the same (run 37198225537). The reader asks its front page once a run whether it has opened and never retries a refusal another way (Sam, sheet 29 card 3)."}], "steps": [{"run": "37166814546", "date": "2026-10-04", "plan": "capture, the pilot sample (capture run 4)", "found": "0 of 4: the views open, but their text names no listed code."}, {"run": "37172202580", "date": "2026-10-04", "plan": "capture through each view's PDF export (capture run 6)", "found": "4 of 4 programs (Fire Technology A.S. 05100 and certificate 18207, Entrepreneurship A.S. 35030, Business Administration 2.0 A.S.-T 41496)."}, {"run": "37197332656", "date": "2026-10-04", "plan": "the sequence probe", "found": "The Program Mapper answers 403 to every request."}], "answers": [{"question": "Where the catalog prints each program's requirements", "status": "answered", "answer": "The program view's PDF export; all four pilot records pass the four checks (Sam, 2026-10-04)."}, {"question": "AUTO 156G's EMT and Driver Operator 1B articulations in MAP", "status": "answered", "answer": "MAP's student-grain table puts both exhibits on EMGM-106 and FIPT-321P (0.25-hour versions); the AUTO 156G link sits on the 0.3-hour versions only in the articulated-exhibit view (S335)."}], "open": [{"question": "Fire Technology A.S. 05100's term-by-term sequence", "next": "The mapper refuses the reader; look for a sequence on the college's own pages and in its catalog, and ask the mapper's front page once a run."}], "nuances": ["A single-program export keeps its top: Fire Technology's exports name FIPT 101 in the outcomes, and a window opened before the first code cut the award heading (lesson 30).", "Miramar lists Early Education Entrepreneurship beside Entrepreneurship; the reader prefers the item that begins with the title, then the shorter item (lesson 32).", "Miramar prints outcomes under Learning Outcome(s):, not a program or student learning outcomes heading.", "The Fire Technology summaries name the optional On Campus Fire Academy cohort courses and FACD 100D; they are not degree requirements.", "Business Administration 2.0 prints ECON C2001 and C2002 where the state file lists ECON 120 and 121."], "requests": [], "workarounds": [{"for": "A curriQunet view that prints only navigation", "tried": "The view's Export Page as PDF; stop clicking at the program's view (lesson 29)", "result": "worked (4 of 4)"}, {"for": "The term-by-term map", "tried": "The Program Mapper (seven requests) and 17 other mapper hosts", "result": "refused by the mapper service"}], "request_ready": false}$proc$::jsonb, 'S344 SkyWaypoint, 2026-10-08 (scheduled run; handoff 344 priority 1)', 'none') as result;
